using System.Diagnostics;
using System.Text;
using System.Text.Json;
using Baxy.Providers.Windows.External;
using NUnit.Framework;

namespace Baxy.Providers.Windows.Tests;

/// <summary>
/// Encargo uso-110 (F11, N1): what a press played is told as it is, whichever way the client was installed and in
/// whichever of the product's languages it shows. Read live on a client with Windows' generated application id
/// (Microsoft.AutoGenerated.{…}, its Start menu link's), where the session was never found as the client's; and on the
/// search «lofi», whose first result «Reproducir Lofi Tarde Clara» played a song of that list told as «not what you
/// asked for».
/// </summary>
[TestFixture]
public sealed class SpotifyPlayedReceiptTests
{
    private const string Generated = "Microsoft.AutoGenerated.{0F0F0F0F-1111-2222-3333-444444444444}";
    private const string Misheard = """{"provider":"spotify","query":"Los Andamius Cobri"}""";
    private const string StaleLine = "marea lenta de nora vidal";
    private const string NewLine = "lluvia de cobre de los andamios";
    private const string NotConfirmed = "spotify_query_result_not_confirmed";
    private const string NotVerified = "spotify_play_clicked_not_verified";

    private static UserMediaSession Loaded(string id, string status = "paused") => new(id, "Marea Lenta", "Nora Vidal", status);

    private static UserMediaSession Result(string id) => new(id, "Lluvia de Cobre", "Los Andamios", "playing");

    private static string Answer(
        bool ok, string? error, string control, string line = StaleLine, string? title = "Los Andamios - Lluvia de Cobre",
        string? evidence = null, string? pressed = null) =>
        JsonSerializer.Serialize(new Dictionary<string, object?>
        {
            ["ok"] = ok,
            ["effectObserved"] = true,
            ["error"] = error,
            ["title"] = title,
            ["selectedControl"] = control,
            ["pressedResult"] = pressed,
            ["beforeNowPlaying"] = StaleLine,
            ["observedNowPlaying"] = line,
            ["playbackEvidence"] = evidence,
            ["processId"] = 42,
        });

    // The live case: Windows names the session by the Start menu link's generated id, and only the shell knows it is
    // the client's. Before this, the search that played came back failed on such an install.
    [Test]
    public async Task ASessionTheShellNamesAsTheClientIsTheClients()
    {
        var adapter = new SpotifyDesktopAdapter(
            new Runner(Answer(false, NotConfirmed, "Reproducir Lluvia de Cobre")),
            sessions: new Sessions([Loaded(Generated)], [Result(Generated)]).Read,
            shownName: id => id == Generated ? "Spotify" : null);

        ExternalCapabilityReceipt receipt = await adapter.InvokeAsync("media.play.query", Json(Misheard), CancellationToken.None);

        Assert.Multiple(() =>
        {
            Assert.That(receipt.Verified, Is.True, receipt.ErrorCode);
            Assert.That(receipt.Result?.GetProperty("observedNowPlaying").GetString(), Is.EqualTo(NewLine));
            Assert.That(receipt.Result?.GetProperty("playbackEvidence").GetString(), Is.EqualTo("media_session_changed"));
        });
    }

    // Controls: another application's session, with a generated id or with the client's name inside its own («Studio by
    // Spotify Labs», read on the same PC), proves nothing about the client.
    [TestCase(Generated, "Un Reproductor")]
    [TestCase(@"C:\Users\p\AppData\Roaming\Studio by Spotify Labs\Studio by Spotify Labs.exe", "Studio by Spotify Labs")]
    public async Task AnotherApplicationsSessionIsNotTheClients(string id, string shown)
    {
        var adapter = new SpotifyDesktopAdapter(
            new Runner(Answer(false, NotConfirmed, "Reproducir Lluvia de Cobre")),
            sessions: new Sessions([Loaded(id)], [Result(id)]).Read,
            shownName: _ => shown);

        ExternalCapabilityReceipt receipt = await adapter.InvokeAsync("media.play.query", Json(Misheard), CancellationToken.None);

        Assert.Multiple(() =>
        {
            Assert.That(receipt.Verified, Is.False);
            Assert.That(receipt.ErrorCode, Is.EqualTo(NotConfirmed));
            Assert.That(receipt.Result?.GetProperty("observedNowPlaying").GetString(), Is.EqualTo(StaleLine));
        });
    }

    // N1, read live: «lofi» pressed the list «Lofi Tarde Clara» and one of its songs plays. What plays holds no word of
    // the search, what was pressed does: it is no mismatch. Control: neither of them holds one.
    [TestCase("Reproducir Lofi Tarde Clara", null, false)]
    [TestCase("Play Lofi Tarde Clara", null, false)]
    [TestCase("Reproducir", "lofi tarde clara", false)]
    [TestCase("Reproducir Grandes Éxitos del Verano", null, true)]
    [TestCase("Reproducir", null, true)]
    [TestCase("Reproducir", "", true)]
    public async Task ASearchIsAMismatchOnlyWhenNeitherWhatPlaysNorWhatWasPressedHoldsItsWords(
        string control, string? pressed, bool mismatch)
    {
        var adapter = new SpotifyDesktopAdapter(new Runner(Answer(
            true, null, control, line: "hojas de papel de tomas arrieta", title: "Tomas Arrieta - Hojas de Papel",
            evidence: "now_playing_changed", pressed: pressed)));

        ExternalCapabilityReceipt receipt = await adapter.InvokeAsync(
            "media.play.query", Json("""{"provider":"spotify","query":"lofi"}"""), CancellationToken.None);

        Assert.Multiple(() =>
        {
            Assert.That(receipt.Verified, Is.True);
            Assert.That(receipt.Result!.Value.TryGetProperty("queryMatched", out _), Is.EqualTo(mismatch));
        });
    }

    // What was pressed tells no mismatch apart; it never tells a press played: a line that did not move and holds no
    // word of the search is still unconfirmed though the control names the search.
    [Test]
    public async Task APressedResultThatNamesTheSearchDoesNotShowItPlayed()
    {
        var adapter = new SpotifyDesktopAdapter(new Runner(Answer(
            true, null, "Reproducir Lofi Tarde Clara", line: StaleLine, title: "Spotify Premium", evidence: "pressed_control_reads_pause")));

        ExternalCapabilityReceipt receipt = await adapter.InvokeAsync(
            "media.play.query", Json("""{"provider":"spotify","query":"lofi"}"""), CancellationToken.None);

        Assert.That(receipt.ErrorCode, Is.EqualTo(NotConfirmed));
    }

    // A press the script never saw taking (a client whose line it cannot read) but whose session moved to the very
    // result pressed did play it. A bare control names nothing, and another result is no proof.
    [TestCase("Reproducir Lluvia de Cobre", true)]
    [TestCase("Reproducir Canción del Faro", false)]
    [TestCase("Reproducir", false)]
    public async Task ASearchNotVerifiedIsConfirmedWhenTheSessionMovedToTheResultPressed(string control, bool verified)
    {
        const string Client = "Spotify.exe";
        var adapter = new SpotifyDesktopAdapter(
            new Runner(Answer(false, NotVerified, control, line: "")),
            sessions: new Sessions([Loaded(Client, "playing")], [Result(Client)]).Read);

        ExternalCapabilityReceipt receipt = await adapter.InvokeAsync("media.play.query", Json(Misheard), CancellationToken.None);

        Assert.Multiple(() =>
        {
            Assert.That(receipt.Verified, Is.EqualTo(verified), receipt.ErrorCode);
            Assert.That(receipt.ErrorCode, Is.EqualTo(verified ? null : NotVerified));
            Assert.That(receipt.Result?.GetProperty("observedNowPlaying").GetString(), Is.EqualTo(NewLine));
        });
    }

    // A title's verdict is its identity: the session moved to that very title is that identity (accents and case aside),
    // another title is not.
    [TestCase("LLUVIA DE COBRE", true)]
    [TestCase("Lluvia", false)]
    public async Task AnExactTitleNotVerifiedIsConfirmedWhenTheSessionMovedToThatTitle(string title, bool verified)
    {
        const string Client = "Spotify.exe";
        var adapter = new SpotifyDesktopAdapter(
            new Runner(Answer(false, NotVerified, "Reproducir " + title, line: "")),
            sessions: new Sessions([Loaded(Client)], [Result(Client)]).Read);

        ExternalCapabilityReceipt receipt = await adapter.InvokeAsync(
            "media.play.exact", Json("{\"provider\":\"spotify\",\"title\":\"" + title + "\"}"), CancellationToken.None);

        Assert.That(receipt.Verified, Is.EqualTo(verified), receipt.ErrorCode);
    }

    // An English client's line (« by ») before the press names its track as a Spanish one's does: a track that ended by
    // itself during the search is not the press's doing.
    [Test]
    public async Task AnEnglishLineBeforeThePressNamesTheTrackToo()
    {
        const string Client = "Spotify.exe";
        string answer = JsonSerializer.Serialize(new Dictionary<string, object?>
        {
            ["ok"] = false,
            ["effectObserved"] = true,
            ["error"] = NotConfirmed,
            ["title"] = "Spotify Premium",
            ["selectedControl"] = "Play Marea Lenta",
            ["beforeNowPlaying"] = "lluvia de cobre by los andamios",
            ["observedNowPlaying"] = "lluvia de cobre by los andamios",
            ["processId"] = 42,
        });
        var adapter = new SpotifyDesktopAdapter(new Runner(answer), sessions: new Sessions([Loaded(Client, "playing")], [Result(Client)]).Read);

        ExternalCapabilityReceipt receipt = await adapter.InvokeAsync("media.play.query", Json(Misheard), CancellationToken.None);

        Assert.That(receipt.ErrorCode, Is.EqualTo(NotConfirmed));
    }

    // The script's own reads, run from its text: the now-playing control and the play control in both of the product's
    // languages. Before this an English client never showed a line (no press could be verified) and an exact title was
    // never found (the control was only looked for as «reproducir <title>»).
    [TestCase("Estás escuchando: Lluvia de Cobre de Los Andamios", "lluvia de cobre de los andamios")]
    [TestCase("Sonando: Lluvia de Cobre de Los Andamios", "lluvia de cobre de los andamios")]
    [TestCase("Now playing: Lluvia de Cobre by Los Andamios", "lluvia de cobre by los andamios")]
    [TestCase("Now playing view", "")]
    [TestCase("Sonando en la Radio", "")]
    [TestCase("Reproducir Lluvia de Cobre", "")]
    public async Task TheScriptReadsTheNowPlayingControlInBothLanguages(string name, string line)
    {
        string answer = await RunFunctionsAsync(
            "Get-BaxySpotifyPlayingLine", $"Get-BaxySpotifyPlayingLine '{name}'");

        Assert.That(answer, Is.EqualTo(line));
    }

    [TestCase("lluvia de cobre de los andamios", "lluvia de cobre", "los andamios", true)]
    [TestCase("lluvia de cobre by los andamios", "lluvia de cobre", "los andamios", true)]
    [TestCase("lluvia de cobre by otros", "lluvia de cobre", "los andamios", false)]
    [TestCase("lluvia de cobre by los andamios", "cobre", "", false)]
    public async Task TheScriptComparesANowPlayingLineOfEitherLanguage(string playing, string title, string identity, bool same)
    {
        string answer = await RunFunctionsAsync(
            "Test-BaxySpotifyNowPlayingIs", $"Test-BaxySpotifyNowPlayingIs '{playing}' '{title}' '{identity}'");

        Assert.That(answer, Is.EqualTo(same ? "True" : "False"));
    }

    [TestCase("reproducir lluvia de cobre", true)]
    [TestCase("play lluvia de cobre", true)]
    [TestCase("play lluvia de cobre los andamios", true)]
    [TestCase("play lluvia de cobrexx", false)]
    [TestCase("pause lluvia de cobre", false)]
    public async Task TheScriptFindsAPlayControlOfATitleInEitherLanguage(string name, bool plays)
    {
        string answer = await RunFunctionsAsync(
            "Test-BaxySpotifyPlaysTitle", $"Test-BaxySpotifyPlaysTitle '{name}' 'lluvia de cobre'");

        Assert.That(answer, Is.EqualTo(plays ? "True" : "False"));
    }

    // Read live: a client not answering leaves a process with a small dialog per «spotify:», and the first with a window
    // was one of those. Controls: a process with no window is none, and with only one there is nothing to choose.
    [TestCase("@(@{MainWindowHandle=5;WorkingSet64=34;Id=1},@{MainWindowHandle=6;WorkingSet64=424;Id=2},@{MainWindowHandle=7;WorkingSet64=34;Id=3})", "2")]
    [TestCase("@(@{MainWindowHandle=0;WorkingSet64=900;Id=1},@{MainWindowHandle=6;WorkingSet64=30;Id=2})", "2")]
    [TestCase("@(@{MainWindowHandle=0;WorkingSet64=900;Id=1})", "")]
    public async Task TheScriptTakesTheClientNotADialogOfAProcessItStarted(string processes, string id)
    {
        string answer = await RunFunctionsAsync(
            "Select-BaxySpotifyClientProcess",
            $"$list={processes}|ForEach-Object {{[pscustomobject]$_}};(Select-BaxySpotifyClientProcess $list).Id");

        Assert.That(answer, Is.EqualTo(id));
    }

    // Runs one call against functions and script-level assignments lifted from the script's text by PowerShell's own
    // parser; the script itself would start the client.
    private static async Task<string> RunFunctionsAsync(string function, string call)
    {
        string path = Path.Combine(AppContext.BaseDirectory, "SpotifyDesktopAutomation.ps1").Replace("'", "''", StringComparison.Ordinal);
        string script = $$"""
            $errors=$null;$tokens=$null
            $ast=[System.Management.Automation.Language.Parser]::ParseFile('{{path}}',[ref]$tokens,[ref]$errors)
            foreach($item in $ast.EndBlock.Statements){
                $text=$item.Extent.Text
                if($item -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $item.Name -in @('Fold','{{function}}')){Invoke-Expression $text}
                elseif($text -like '$script:BaxySpotifyPlaying*'){Invoke-Expression $text}
            }
            {{call}}
            """;
        var start = new ProcessStartInfo("powershell.exe")
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };
        foreach (string argument in new[] { "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-EncodedCommand" })
            start.ArgumentList.Add(argument);
        start.ArgumentList.Add(Convert.ToBase64String(Encoding.Unicode.GetBytes(script)));
        using Process process = Process.Start(start) ?? throw new InvalidOperationException("powershell did not start");
        Task<string> error = process.StandardError.ReadToEndAsync();
        string output = ChildOutput.Read(process);
        Assert.That(process.WaitForExit(60_000), Is.True, "the script answers");
        // Windows PowerShell writes its progress to the error stream as CLIXML: only the exit code tells a failure.
        Assert.That(process.ExitCode, Is.EqualTo(0), await error);
        return output.Trim();
    }

    private static JsonElement Json(string text)
    {
        using JsonDocument document = JsonDocument.Parse(text);
        return document.RootElement.Clone();
    }

    // Each read answers the next list; the last one stands.
    private sealed class Sessions(params UserMediaSession[][] reads)
    {
        private int _reads;

        internal Task<IReadOnlyList<UserMediaSession>> Read(CancellationToken cancellationToken)
        {
            IReadOnlyList<UserMediaSession> read = reads[Math.Min(_reads, reads.Length - 1)];
            _reads++;
            return Task.FromResult(read);
        }
    }

    private sealed class Runner(string output) : IExternalProcessRunner
    {
        public ValueTask<ExternalProcessResult> RunAsync(
            string executable, IReadOnlyList<string> arguments, TimeSpan timeout, CancellationToken cancellationToken) =>
            ValueTask.FromResult(new ExternalProcessResult(0, output, ""));
    }
}
